def merge_tool_results(calls, results):
    seen = set()
    for c in calls:
        cid = c["id"]
        if cid in seen:
            raise ValueError(f"duplicate call id {cid!r}")
        seen.add(cid)

    by_id = {}
    for r in results:
        by_id[r["id"]] = r.get("content", "")

    return [
        {"id": c["id"], "status": "done", "content": by_id[c["id"]]}
        if c["id"] in by_id
        else {"id": c["id"], "status": "pending"}
        for c in calls
    ]

