def summarize_usage(events):
    """Sum token usage across requests.

    Each event has a 'request_id' and optional nonnegative integer 'input' and
    'output' counts (cumulative snapshots for that request). For each request the
    maximum seen input and output are kept independently, then those maxima are
    summed across requests. Missing counts count as 0; a negative count raises
    ValueError. Events are not mutated.
    """
    best = {}
    for ev in events:
        rid = ev['request_id']
        inp = ev.get('input', 0)
        out = ev.get('output', 0)
        if inp < 0 or out < 0:
            raise ValueError(f"negative token count: input={inp!r} output={out!r}")
        cur = best.get(rid)
        if cur is None:
            best[rid] = [inp, out]
        else:
            if inp > cur[0]:
                cur[0] = inp
            if out > cur[1]:
                cur[1] = out
    return {'input': sum(c[0] for c in best.values()),
            'output': sum(c[1] for c in best.values())}

